function getExamChronologicalScore(name, year) {
  let score = (parseInt(year) || 2000) * 100;
  const n = (name || '').toLowerCase();
  if (n.includes('kasım') || n.includes('yds/3') || n.includes('yds 3') || n.includes('sonbahar') || n.includes('ekim') || n.includes('yds/2') || n.includes('yds 2')) {
    if (n.includes('yds/3') || n.includes('yds 3')) score += 30;
    else score += 20;
  } else if (n.includes('ilkbahar') || n.includes('nisan') || n.includes('mart') || n.includes('yds/1') || n.includes('yds 1')) {
    score += 10;
  }
  return score;
}

